(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035+t*0.5)*8 + Math.cos((y+w1y)*0.025-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03-t*0.45)*8 + Math.sin((x+w1x)*0.028+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 1.05]
  ];
  let aS=0, iS=0, dS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    dS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0) * w * 0.5;
  }
  const n = src.length, tw = src.reduce((a,s)=>a+s[4],0);
  const act=aS/tw, inh=iS/tw, dif=dS/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = (Math.sin(dist*0.07+ang*2-t*0.8)+Math.cos(dist*0.03-ang*5+t*1.7))*0.25;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + sp1)*2.2);
  const rd2 = Math.tanh((dif*0.8 + inh*0.5 - act*0.3 + sp2 + ripple)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi = Math.sin(Math.floor(sx/20)*12.9898+Math.floor(sy/20)*78.233+t)*0.5+0.5;
  const blend = rd1*0.5 + rd2*0.2 + cell*0.15 + voronoi*0.05 + (sp1+sp2)*0.1;
  const v = blend*0.5+0.5;
  const edge = Math.abs(rd1)>0.65 ? 1.2 : Math.abs(rd2)>0.6 ? 1.1 : 1.0;
  const glow = Math.max(0, 1-Math.abs(rd1)*1.5)*0.15;
  const lum = 0.8 + Math.sin(rd1*Math.PI)*0.2 + glow;
  const pal = [[5,10,45],[10,45,85],[15,95,120],[25,155,145],[180,175,60],[215,130,65],[175,60,70],[90,25,55],[30,15,65],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
